struct sk_buff *reassemble_ipv6_fragments(struct nf_ct_frag6_queue *fq, struct net_device *dev) {
    struct sk_buff *skb = NULL;
    struct sk_buff *frag;
    unsigned int payload_len = 0;
    int err;

    if (!fq || !dev)
        return NULL;

    skb = alloc_skb(fq->payload_len, GFP_ATOMIC);
    if (!skb) {
        pr_debug("Memory allocation failure for IPv6 reassembly.\n");
        return NULL;
    }

    skb->dev = dev;
    skb->protocol = htons(ETH_P_IPV6);

    /* Copy data from each fragment */
    for (frag = fq->fragments; frag; frag = frag->next) {
        payload_len += frag->len;

        if (skb_tailroom(skb) < frag->len) {
            pr_debug("Insufficient buffer space for fragment.\n");
            kfree_skb(skb);
            return NULL;
        }

        skb_put_data(skb, frag->data, frag->len);
    }

    skb->len = payload_len;
    skb->data_len = payload_len;
    skb->truesize = payload_len;

    /* Adjust headers and checksums as needed */
    err = ip6_reassemble(skb, 0);
    if (err) {
        pr_debug("IPv6 reassembly failed with error code %d.\n", err);
        kfree_skb(skb);
        return NULL;
    }

    return skb;
}

struct sk_buff *reassemble_ipv6_fragments(struct nf_ct_frag6_queue *fq,
                                          struct net_device *dev) {
    struct sk_buff *skb;
    int payload_len;
    int i;

    if (!fq || !dev) {
        return NULL;
    }

    payload_len = 0;
    for (i = 0; i < fq->q.pf; i++) {
        struct sk_buff *frag = fq->q.fragments[i];
        payload_len += frag->len;
    }

    skb = alloc_skb(payload_len, GFP_ATOMIC);
    if (!skb) {
        pr_debug("Failed to allocate memory for reassembled packet.\n");
        return NULL;
    }

    skb->dev = dev;
    skb->protocol = htons(ETH_P_IPV6);

    for (i = 0; i < fq->q.pf; i++) {
        struct sk_buff *frag = fq->q.fragments[i];
        int offset = frag->data - frag->head;

        if (!skb_copy_bits(frag, offset, skb_put(skb, frag->len), frag->len)) {
            pr_debug("Failed to copy fragment data.\n");
            kfree_skb(skb);
            return NULL;
        }
    }

    ip6_hdr(skb)->payload_len = htons(payload_len);
    skb->len = sizeof(struct ipv6hdr) + payload_len;
    skb->data_len = skb->len;

    return skb;
}

struct sk_buff *reassemble_ipv6_fragments(struct nf_ct_frag6_queue *fq, struct net_device *dev)
{
    struct sk_buff *skb;
    struct ipv6hdr *ipv6_hdr;
    int payload_len;
    int ret;

    if (!fq || !dev) {
        return NULL;
    }

    payload_len = nf_ct_frag6_queue_payload_len(fq);
    if (payload_len < 0) {
        return NULL;
    }

    skb = alloc_skb(payload_len + sizeof(struct ipv6hdr), GFP_ATOMIC);
    if (!skb) {
        return NULL;
    }

    skb_reserve(skb, sizeof(struct ipv6hdr));

    ret = nf_ct_frag6_queue_build_skb(fq, skb);
    if (ret < 0) {
        kfree_skb(skb);
        return NULL;
    }

    ipv6_hdr = skb_push(skb, sizeof(struct ipv6hdr));
    memset(ipv6_hdr, 0, sizeof(struct ipv6hdr));
    ipv6_hdr->version = 6;
    ipv6_hdr->payload_len = htons(payload_len);
    ipv6_hdr->nexthdr = fq->frag->ipv6h->nexthdr;
    ipv6_hdr->saddr = fq->frag->ipv6h->saddr;
    ipv6_hdr->daddr = fq->frag->ipv6h->daddr;

    skb->dev = dev;
    skb->protocol = htons(ETH_P_IPV6);
    skb->pkt_type = PACKET_HOST;
    skb->ip_summed = CHECKSUM_NONE;

    nf_ct_frag6_queue_destroy(fq);
    return skb;
}

struct sk_buff *reassemble_ipv6_fragments(struct nf_ct_frag6_queue *fq, struct net_device *dev)
{
    int payload_len;
    struct sk_buff *skb;

    if (!fq || !dev)
        return NULL;

    payload_len = nf_ct_frag6_queue_payload_len(fq);
    if (payload_len < 0)
        return NULL;

    skb = alloc_skb(payload_len, GFP_ATOMIC);
    if (!skb)
        return NULL;

    if (fq->first && (fq->first->flags & IP6_FLAGS_MORE_FRAG)) {
        if (payload_len < (fq->first->offset + 1)) {
            kfree_skb(skb);
            return NULL;
        }
    }

    skb->len = payload_len;
    skb->data_len = payload_len;

    while (!skb_queue_empty(&fq->fragments)) {
        struct sk_buff *fragment = skb_dequeue(&fq->fragments);

        if (!fragment)
            break;

        skb_copy_from_linear_data_offset(fragment, 0, skb->data + fragment->offset,
                                           fragment->len);
    }

    ip6_hdr(skb)->payload_len = htons(payload_len);
    skb->ip_summed = CHECKSUM_NONE;

    return skb;
}

struct sk_buff *reassemble_ipv6_fragments(struct nf_ct_frag6_queue *fq, struct net_device *dev) {
    struct sk_buff *skb;
    int payload_len;
    int i;

    if (!fq || !dev) {
        return NULL;
    }

    payload_len = 0;
    for (i = 0; i < fq->q.pf->q.pf->q.fragments; i++) {
        payload_len += fq->q.fragments[i].data_len;
    }

    skb = alloc_skb(payload_len, GFP_ATOMIC);
    if (!skb) {
        pr_debug("Memory allocation failed during IPv6 reassembly.\n");
        return NULL;
    }

    if (fq->q.fragments[0].flags & MORE_FRAGMENTS) {
        pr_debug("First fragment is itself fragmented.\n");
        kfree_skb(skb);
        return NULL;
    }

    for (i = 0; i < fq->q.fragments; i++) {
        if (skb_copy_from_linear_data(skb, fq->q.fragments[i].data, fq->q.fragments[i].data_len)) {
            pr_debug("Failed to copy fragment data during reassembly.\n");
            kfree_skb(skb);
            return NULL;
        }
    }

    skb->len = payload_len;
    skb->data_len = payload_len;
    skb->truesize = payload_len;

    /* Adjust IPv6 headers and checksums as needed */
    ip6_hdr(skb)->payload_len = htons(payload_len);

    return skb;
}
